import React, { useState } from 'react';
import { createAppointment } from '../../api/api';

function CreateAppointment() {
  const [form, setForm] = useState({ patient_name: '', date: '', description: '' });

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    try {
      await createAppointment(form);
      alert('Cita agendada correctamente');
    } catch (err) {
      console.error('Error agendando cita', err);
    }
  };

  return (
    <div>
      <h2>Agendar Nueva Cita</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" name="patient_name" placeholder="Paciente" onChange={handleChange} />
        <input type="datetime-local" name="date" onChange={handleChange} />
        <input type="text" name="description" placeholder="Descripción" onChange={handleChange} />
        <button type="submit">Agendar</button>
      </form>
    </div>
  );
}

export default CreateAppointment;
